// Fixture persona pool (jp), Nemotron row shape. Small but demographically
// varied so filter/cluster tests exercise real branching.

import type { RawPersona } from "../../src/types";

function p(
  n: number,
  age: number,
  sex: "男" | "女",
  occupation: string,
  region: string,
  locality: string,
  name: string,
  blurb: string,
): RawPersona {
  return {
    uuid: `jp-${String(n).padStart(3, "0")}`,
    country: "jp",
    age,
    sex,
    sex_norm: sex === "男" ? "M" : "F",
    occupation,
    marital_status: age > 32 ? "既婚" : "未婚",
    education_level: "大学卒",
    region,
    locality,
    professional_persona: `${name}は、${locality}在住の${age}歳の${occupation}。${blurb}`,
    persona: blurb,
  };
}

